namespace Mcrf.Wpf {
 public sealed class CellPresenter : ContentControl {
  public static readonly DependencyProperty CreateProperty=DependencyProperty.Register("Create",typeof(Func<object,UIElement>),typeof(CellPresenter),new PropertyMetadata(null,(s,e)=>((CellPresenter)s).Refresh()));
  public Func<object,UIElement> Create{get{return (Func<object,UIElement>)GetValue(CreateProperty);}set{SetValue(CreateProperty,value);}}
  public CellPresenter(){DataContextChanged+=(s,e)=>Refresh();Loaded+=(s,e)=>Refresh();HorizontalContentAlignment=HorizontalAlignment.Stretch;}
  void Refresh(){Content=Create==null||DataContext==null?null:Create(DataContext);}
 }
 public sealed class WorkspaceDialog : Window {
  bool framing;MainWindow backdropOwner;readonly System.Windows.Threading.DispatcherTimer dismissal=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(40)};bool pressed;
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern short GetAsyncKeyState(int key);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool GetCursorPos(out CursorPoint point);
  [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct CursorPoint{public int X,Y;}
  internal static bool OutsideDialog(Point point,Rect owner,Rect dialog){return owner.Contains(point)&&!dialog.Contains(point);}
  void PollDismissal(){bool down=(GetAsyncKeyState(1)&0x8000)!=0||(GetAsyncKeyState(5)&0x8000)!=0;bool edge=down&&!pressed;pressed=down;if(!edge||!IsEnabled||!IsActive||backdropOwner==null||!IsVisible||Mouse.Captured!=null)return;CursorPoint mouse;if(!GetCursorPos(out mouse))return;var mainRect=new Rect(backdropOwner.PointToScreen(new Point(0,0)),backdropOwner.PointToScreen(new Point(backdropOwner.ActualWidth,backdropOwner.ActualHeight)));var dialogRect=new Rect(PointToScreen(new Point(0,0)),PointToScreen(new Point(ActualWidth,ActualHeight)));if(OutsideDialog(new Point(mouse.X,mouse.Y),mainRect,dialogRect))Close();}

  public WorkspaceDialog(){WindowStyle=WindowStyle.None;Background=Brushes.Transparent;AllowsTransparency=true;ResizeMode=ResizeMode.CanResize;ShowInTaskbar=false;UseLayoutRounding=true;SnapsToDevicePixels=true;WindowChrome.SetWindowChrome(this,new WindowChrome{CaptionHeight=62,ResizeBorderThickness=new Thickness(6),GlassFrameThickness=new Thickness(0),CornerRadius=new CornerRadius(18),UseAeroCaptionButtons=false});Loaded+=(s,e)=>{Window owner=Owner;while(owner!=null&&!(owner is MainWindow))owner=owner.Owner;backdropOwner=owner as MainWindow;if(backdropOwner!=null)backdropOwner.EnterModal();pressed=(GetAsyncKeyState(1)&0x8000)!=0;dismissal.Start();};dismissal.Tick+=(s,e)=>PollDismissal();PreviewMouseDown+=(s,e)=>{if(e.ChangedButton==MouseButton.XButton1){Close();e.Handled=true;}};Closed+=(s,e)=>{dismissal.Stop();if(backdropOwner!=null)backdropOwner.ExitModal();};PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Escape){if(!MainWindow.CancelChordCapture(Keyboard.FocusedElement as DependencyObject))Close();e.Handled=true;}};}
  protected override void OnContentChanged(object oldContent,object newContent){base.OnContentChanged(oldContent,newContent);if(framing||newContent==null)return;framing=true;Content=null;var layout=new DockPanel();var heading=new Grid{Margin=new Thickness(20,14,20,0)};heading.ColumnDefinitions.Add(new ColumnDefinition());heading.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(38)});heading.Children.Add(new TextBlock{Text=Title,FontSize=24,Foreground=Foreground,VerticalAlignment=VerticalAlignment.Center});var close=new Button{Content="×",Width=38,Height=38,Padding=new Thickness(0),FontSize=22};close.Click+=(s,e)=>Close();Grid.SetColumn(close,1);WindowChrome.SetIsHitTestVisibleInChrome(close,true);heading.Children.Add(close);DockPanel.SetDock(heading,Dock.Top);layout.Children.Add(heading);layout.Children.Add(newContent as UIElement??new ContentPresenter{Content=newContent});Content=new Border{Background=(Brush)Application.Current.FindResource("GlassDialogSurface"),CornerRadius=new CornerRadius(18),BorderBrush=new SolidColorBrush(Color.FromRgb(44,56,82)),BorderThickness=new Thickness(1),Child=layout};framing=false;}
 }
 public sealed partial class MainWindow {
  static WrapPanel CompactTools(params Button[] buttons){var panel=new WrapPanel{Margin=new Thickness(0,6,0,12)};foreach(var button in buttons){button.MinWidth=136;button.Margin=new Thickness(0,0,12,0);panel.Children.Add(button);}return panel;}
  static UniformGrid Toolbar(params Button[] buttons){var grid=new UniformGrid{Columns=Math.Max(1,buttons.Length),Margin=new Thickness(0,0,0,10)};for(int i=0;i<buttons.Length;i++){buttons[i].Margin=new Thickness(0,0,i==buttons.Length-1?0:12,0);grid.Children.Add(buttons[i]);}Action layout=()=>grid.Columns=Math.Max(1,buttons.Count(b=>b.Visibility!=Visibility.Collapsed));foreach(var b in buttons)b.IsVisibleChanged+=(s,e)=>layout();layout();return grid;}
  static Grid Columns(UIElement left,UIElement right,double ratio=1){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(ratio,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(16)});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.Children.Add(left);Grid.SetColumn(right,2);grid.Children.Add(right);return grid;}
  static StackPanel Field(string label,UIElement control){var panel=new StackPanel();panel.Children.Add(Text(label));panel.Children.Add(control);return panel;}
  static DataGridTemplateColumn CellColumn(string heading,double width,Func<object,UIElement> create){var factory=new FrameworkElementFactory(typeof(CellPresenter));factory.SetValue(CellPresenter.CreateProperty,create);return new DataGridTemplateColumn{Header=heading,Width=new DataGridLength(width,DataGridLengthUnitType.Star),CellTemplate=new DataTemplate{VisualTree=factory},CanUserSort=false};}
  Button ServicePicker(CheckBox[] checks,string caption="Сервисов"){var button=new Button{MinWidth=140,Height=30,VerticalAlignment=VerticalAlignment.Top};var list=new StackPanel{Margin=new Thickness(14)};foreach(var check in checks)list.Children.Add(check);var popup=new Popup{PlacementTarget=button,Placement=PlacementMode.Bottom,StaysOpen=false,AllowsTransparency=true,Child=new Border{Background=Brush("#202D46"),CornerRadius=new CornerRadius(12),BorderBrush=Brush("#465878"),BorderThickness=new Thickness(1),Child=new ScrollViewer{Content=list,MaxHeight=320,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}}};Action refresh=()=>button.Content=caption+": "+checks.Count(c=>c.IsChecked==true);foreach(var check in checks){check.Checked+=(s,e)=>refresh();check.Unchecked+=(s,e)=>refresh();}button.Click+=(s,e)=>popup.IsOpen=!popup.IsOpen;button.Unloaded+=(s,e)=>popup.IsOpen=false;refresh();return button;}
  void Notice(string message,string heading="MCRF"){var window=Dialog(heading,660,300);var panel=new DockPanel{Margin=new Thickness(24)};var ok=Button("Понятно",()=>window.DialogResult=true);ok.HorizontalAlignment=HorizontalAlignment.Right;ok.MinWidth=150;DockPanel.SetDock(ok,Dock.Bottom);panel.Children.Add(ok);panel.Children.Add(new ScrollViewer{Content=Text(message),VerticalScrollBarVisibility=ScrollBarVisibility.Auto});window.Content=panel;window.ShowDialog();}
  bool Confirm(string message,string heading){var window=Dialog(heading,660,320);var panel=new DockPanel{Margin=new Thickness(24)};var actions=Toolbar(Button("Продолжить",()=>window.DialogResult=true),Button("Отмена",()=>window.DialogResult=false));DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);panel.Children.Add(new ScrollViewer{Content=Text(message),VerticalScrollBarVisibility=ScrollBarVisibility.Auto});window.Content=panel;return window.ShowDialog()==true;}
 }
}
